assertionResults.fullName:
public UTF-8 signature conversion: try:
    str(b'\xef\xbb\xbf\xff', 'utf-8-sig')
except UnicodeDecodeError as error:
    assert (error.encoding, error.object, error.start, error.end, error.reason) == ('utf-8', b'\xff', 0, 1, 'invalid start byte')
else:
    assert False

